// ── Total insurance expected (supports both old 'ins' and new ins1Amt/ins2Amt fields) ──
function totalInsExp(entry) {
  // New format: ins1Amt + ins2Amt + ins3Amt
  const n1 = parseFloat(entry.ins1Amt)||0;
  const n2 = parseFloat(entry.ins2Amt)||0;
  const n3 = parseFloat(entry.ins3Amt)||0;
  if (n1+n2+n3 > 0) return n1+n2+n3;
  // Old format: single 'ins' field
  return parseFloat(entry.ins)||0;
}

