// ── Insurance Details Tooltip ────────────────────────────────────────────────
function InsDetailsTooltip({details}) {
  const [show, setShow] = React.useState(false);
  const [pos, setPos] = React.useState({top:0,left:0});
  const iconRef = React.useRef(null);
  const panelRef = React.useRef(null);

  const toggle = (e) => {
    e.stopPropagation();
    if(show){ setShow(false); return; }
    if(iconRef.current){
      const r = iconRef.current.getBoundingClientRect();
      const spaceBelow = window.innerHeight - r.bottom;
      const above = spaceBelow < 250;
      setPos({
        top: above ? r.top + window.scrollY : r.bottom + window.scrollY + 4,
        left: Math.max(4, r.right + window.scrollX - 240),
        above
      });
    }
    setShow(true);
  };

  // Close on click outside
  React.useEffect(()=>{
    if(!show) return;
    const handler = (e)=>{
      if(panelRef.current&&!panelRef.current.contains(e.target)&&iconRef.current&&!iconRef.current.contains(e.target)){
        setShow(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return ()=>document.removeEventListener('mousedown', handler);
  },[show]);
  if (!details) return null;
  const d = details;
  const rows = [
    d.subscriber   ? ['Subscriber',   d.subscriber]   : null,
    d.subDob       ? ['Sub DOB',      d.subDob]        : null,
    d.ptDob        ? ['Pt DOB',       d.ptDob]         : null,
    d.memberId     ? ['Member ID',    d.memberId]      : null,
    d.authId       ? ['Auth ID',      d.authId]        : null,
    d.groupId      ? ['Group',        d.groupId + (d.groupName ? ' · ' + d.groupName : '')] : null,
    d.examPlanId   ? ['Exam Plan ID', d.examPlanId + (d.examPlanName ? ' · ' + d.examPlanName : '')] : null,
    d.examCopay    ? ['Exam',         d.examCopay]     : null,
    d.retinal      ? ['Retinal',      d.retinal]       : null,
    d.clFit        ? ['CL Fit',       d.clFit]         : null,
    d.contacts     ? ['Contacts',     d.contacts]      : null,
    d.frame        ? ['Frame',        d.frame]         : null,
    d.specialNotes ? ['⚠ Notes',      d.specialNotes]  : null,
    d.greatNews    ? ['💡 Tip',        d.greatNews]     : null,
  ].filter(Boolean);

  return (
    <span style={{position:'absolute',top:2,right:2,zIndex:10}}>
      <span ref={iconRef} onClick={toggle}
        style={{fontSize:9,color:show?'#0E7490':'#0891B2',cursor:'pointer',userSelect:'none',fontWeight:show?700:400}}>ℹ</span>
      {show&&(
        <div ref={panelRef}
          style={{position:'fixed',top:pos.above?'auto':pos.top,bottom:pos.above?`calc(100vh - ${pos.top}px)`:'auto',
          left:pos.left,background:'white',border:'1px solid #A5F3FC',borderRadius:8,
          padding:'8px 10px',zIndex:9999,minWidth:240,maxWidth:320,
          boxShadow:'0 4px 16px rgba(0,0,0,0.15)',fontSize:10,
          transform:pos.above?'translateY(-100%)':'none'}}>
          {rows.map(([label, val])=>(
            <div key={label} style={{display:'flex',gap:6,marginBottom:3,alignItems:'flex-start'}}>
              <span style={{color:'#64748B',fontWeight:600,minWidth:70,flexShrink:0}}>{label}:</span>
              <span style={{color:'#1B3A5C'}}>{val}</span>
            </div>
          ))}
        </div>
      )}
    </span>
  );
}

