// ── Square payment panel ─────────────────────────────────────────────────────
const SQUARE_WORKER = 'https://spark-square.ilikebroccoli.workers.dev';

const DEVICE_TO_LOC = {
  'santa clara ipad': 'SC',
  'fremont ipad':     'F',
  'walnut creek ipad 2.0': 'WC',
  'sunnyvale ipad':   'SV',
};

// ── Parse TAB insurance report → [{name, payor, insDetails}] ────────────────
function parseInsuranceText(text, payorList=[], payorAliases=[]) {
  const mapPayor = (raw) => {
    const r = (raw||'').toLowerCase().trim();
    // Check aliases first (admin-defined overrides)
    const alias = payorAliases.find(a => r.includes(a.from.toLowerCase()));
    if (alias) return alias.to;
    // Check specific insurance names FIRST before self
    if (r.includes('vsp')) return 'VSP';
    if (r.includes('eyemed')||r.includes('eye med')) return 'EM';
    if (r.includes('uhc')||r.includes('united')) return 'UHC';
    if (r.includes('spectera')) return 'UHC';
    if (r.includes('medi-cal')||r.includes('medicaid')||r.includes('medi cal')) return 'MediCal';
    if (r.includes('medicare')) return 'Medicare';
    if (r.includes('anthem')) return 'Anthem';
    if (r.includes('aetna')&&r.includes('avp')) return 'Aetna'; // Aetna AVP → Aetna (EyeMed)
    if (r.includes('aetna')) return 'Aetna';
    if (r.includes('metlife')) return 'VSP'; // MetLife uses VSP network
    if (r.includes('guardian')) return 'Guardian';
    if (r.includes('health net')||r.includes('healthnet')) return 'HealthNet';
    if (r.includes('cigna')&&(r.includes('/em')||r.includes(' em')||r.includes('eyemed'))) return 'EM'; // CIGNA/EM → EyeMed
    if (r.includes('cigna')) return 'Cigna';
    if (r.includes('bluecross')||r.includes('blue cross')||r.includes('blue shield')||r.includes('bcbs')) return 'BCBS';
    if (r.includes('davis vision')||r==='davis'||r.startsWith('davis')) return 'DV';
    if (r.includes('superior')) return 'SUP';
    if (r.includes('nva')) return 'NVA';
    if (r.includes('avesis')) return 'Avesis';
    if (r.includes('fep')) return 'FEP';
    if (r.includes('vba')) return 'VBA';
    if (r.includes('heritage')) return 'Heritage';
    // Try to match against current payorList by label — word-level matching
    const matched = payorList.find(p => {
      const labelWords = p.label.toLowerCase().split(/\s+/);
      return labelWords.some(word => word.length > 3 && r.includes(word));
    });
    if (matched) return matched.value;
    // Self/OOP last — only if no insurance found
    if (r.includes('oop')||r.includes('out of pocket')||r===('self')||r.startsWith('self ')) return 'Self';
    return (raw.trim().split(/\s+/)[0])||'';
    if (r.includes('mes')) return 'MES';
    return (raw.trim().split(/\s+/)[0])||'';
  };

  const extractDetails = (block) => {
    const find = (pattern) => { const m=block.match(pattern); return m?m[1].trim():null; };
    const subscriber = find(/Subscriber\s*:\s*([A-Z][A-Z,\s]+?)(?:\s+Subscriber Date|\s+Subscriber Id|\s+Insurance)/);
    let memberId = find(/(?:Subscriber Id|Insurance Id)\s*:\s*(\S+)/);
    if (!memberId||memberId==='N/A') memberId = find(/PrimeInsPolicy:\s*(\S+)/);
    const authId = find(/Authorization ID\s*:\s*(\S+)/);
    const groupId = find(/Group Id\s*:\s*(\S+)/);
    const groupName = find(/Group Name\s*:\s*(.+?)(?:\s+Showing|\s+Member Benefits|\n|$)/);
    const examCopay = find(/Exam Services\s+Exam\s+(.+?)(?:\s+Retinal|\s+Contact Lens Fit|\s+Frame|\n)/)||find(/Exam Copay\s+(.+?)(?:\s+Frame|\s+Contacts|\n)/);
    const retinal = find(/Retinal Imaging\s+(.+?)(?:\s+Contact Lens Fit|\s+Frame|\n)/);
    const contacts = find(/Contacts - Disposable\s+(.+?)(?:\s+Contacts - Med|\s+Other|\n)/)||find(/Contacts - Conventional\s+(.+?)(?:\s+Contacts|\s+Other|\n)/);
    const frame = find(/Frame\s+Frame\s+(.+?)(?:\s+(?:Lenses|Contact|Lens P)|\n)/);
    const clFit = find(/Fit and Follow-up - Standard\s+(.+?)(?:\s+Fit and|\s+Frame|\n)/);
    const subDob = find(/Subscriber Date of Birth\s*:\s*([\d/*]+)/);
    const ptDob = find(/^DOB:\s*([\d/]+)/m);
    const examPlanId = find(/Exam\s*:\s*Plan Id\s*:\s*(\d+)/);
    const examPlanName = find(/Exam\s*:\s*Plan Id\s*:\s*\d+\s*Plan Name\s*:\s*(.+?)(?:\s+Authorization|\s+Independent)/);
    const d = {};
    if (subscriber) d.subscriber = subscriber;
    if (subDob) d.subDob = subDob;
    if (ptDob && ptDob !== subDob) d.ptDob = ptDob;
    if (memberId && memberId!=='N/A') d.memberId = memberId;
    if (authId && authId!=='N/A') d.authId = authId;
    if (groupId) d.groupId = groupId;
    if (groupName) d.groupName = groupName;
    if (examPlanId) d.examPlanId = examPlanId;
    if (examPlanName) d.examPlanName = examPlanName;
    if (examCopay) d.examCopay = examCopay;
    if (retinal) d.retinal = retinal;
    if (clFit) d.clFit = clFit;
    if (contacts) d.contacts = contacts;
    if (frame) d.frame = frame;
    // VSP special notes — "You MUST enter Member ID..." etc.
    const specialNotes = find(/Member\s*-?\s*Special Notes\s+(.+?)(?:\s+Plan allows|\s+Great News!|\s+Important|$)/);
    const greatNews = find(/Great News!\s+(.+?)(?:\s+Important|\s+Member\s*-|$)/);
    if (specialNotes) d.specialNotes = specialNotes;
    if (greatNews) d.greatNews = greatNews;
    return Object.keys(d).length>0 ? d : null;
  };

  const results=[];
  const lines=text.split('\n');
  let currentName=null;
  let currentBlock=[];

  const flush = () => {
    if(!currentName) return;
    const block=currentBlock.join('\n');
    const insMatch=block.match(/PrimeInsCo:\s*(.+)/i);
    if(insMatch){
      const secMatch=block.match(/SecInsCo:\s*(.+)/i);
      results.push({
        name:currentName,
        payor:mapPayor(insMatch[1]),
        raw:insMatch[1].trim(),
        payor2:secMatch?mapPayor(secMatch[1]):null,
        insDetails:extractDetails(block),
      });
    }
    currentName=null;
    currentBlock=[];
  };

  for(let i=0;i<lines.length;i++){
    const line=lines[i];
    const trimmed=line.trim();
    const tabParts=line.split('\t');
    const lastPart=(tabParts[tabParts.length-1]||'').trim();
    // Detect new patient — time line with name at end
    const isTimeLine=tabParts[0]&&/^\d{2}:\d{2}/.test(tabParts[0].trim());
    const nameMatch=lastPart.match(/^([A-Z][A-Za-z\s\-']+,\s*[A-Z][A-Za-z\s\-']+)/);
    if(isTimeLine&&nameMatch){
      flush();
      currentName=nameMatch[1].trim();
      currentBlock=[line];
    } else if(currentName){
      currentBlock.push(line);
    }
  }
  flush();
  return results;
}

// Square catalog item name → billing column mapping
// Each entry: { col: field name, otherType: if goes to other/otherAmt, split: special logic }
const SQUARE_ITEM_MAP = [
  { match: 'Exam Copay - Contact Lens',          col: 'cl' },
  { match: 'Exam Copay - General Eye Exam',       col: 'exam' },
  { match: 'Exam, Private Pay - Contact Lens',    col: 'exam',   split: 'exam_cl' },
  { match: 'Exam, Private Pay - General Eye Exam',col: 'exam' },
  { match: 'Exam, Private Pay - Office Visit',    col: 'ov' },
  { match: 'Imaging - OCT Scan',                  col: 'oct' },
  { match: 'Imaging - iWellness OCT Scan',        col: 'oct' },
  { match: 'Imaging - iWellness Scan',            col: 'oct' },
  { match: 'Imaging - Iwellness Scan',            col: 'oct' },
  { match: 'iWellness Scan',                      col: 'oct' },
  { match: 'OCT Scan',                            col: 'oct' },
  { match: 'Imaging - Optomap Scan',              col: 'optos',  split: 'optos_oct' },
  { match: 'Materials - Contact Lenses',          col: 'otherAmt', otherType: 'Contact Lens Materials' },
  { match: 'Materials - Oasis Products',          col: 'otherAmt', otherType: 'Oasis Materials' },
  { match: 'Missed Appointment Fee',              col: 'otherAmt', otherType: 'No-Show Fee' },
  { match: 'Myopia Control',                      col: 'myopia' },
  { match: 'Scan - Axial Length',                 col: 'otherAmt', otherType: 'Axial Length' },
  { match: 'Scan - Corneal Topography',           col: 'otherAmt', otherType: 'Topo' },
  { match: 'Scan - Pachymetry',                   col: 'otherAmt', otherType: 'Pachymetry' },
  { match: 'Service - Contact Lens Training',     col: 'otherAmt', otherType: 'Contact Lens Training' },
  { match: 'Service - Dilation',                  col: 'dfe' },
  { match: 'Service - Refraction Only',           col: 'otherAmt', otherType: 'Refraction Only' },
];

function getSquareItemMapping(itemName) {
  if (!itemName) return null;
  const normalized = itemName.toLowerCase().trim();
  // Exact match first
  const exact = SQUARE_ITEM_MAP.find(m => m.match.toLowerCase() === normalized);
  if (exact) return exact;
  // Partial match — item name contains the mapping key or vice versa
  const partial = SQUARE_ITEM_MAP.find(m => 
    normalized.includes(m.match.toLowerCase()) || m.match.toLowerCase().includes(normalized)
  );
  return partial || null;
}

function deviceToLoc(deviceName) {
  if (!deviceName) return null;
  return DEVICE_TO_LOC[deviceName.toLowerCase().trim()] || null;
}

function fmtTime(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleTimeString('en-US', {hour:'numeric', minute:'2-digit', hour12:true, timeZone:'America/Los_Angeles'});
}

function squareNameSim(note, patientName) {
  if (!note || !patientName) return 0;
  const n = note.toUpperCase().replace(/[^A-Z\s\n]/g,'').trim();
  const p = patientName.toUpperCase().replace(/[^A-Z\s]/g,'').trim();

  // note might have multiple names separated by newline — check each line
  const noteLines = n.split(/[\n,]+/).map(l=>l.trim()).filter(Boolean);

  let best = 0;
  for (const line of noteLines) {
    const noteToks = line.split(/\s+/).filter(t=>t.length>=2);
    const nameToks = p.split(/\s+/).filter(t=>t.length>=2);
    if (!noteToks.length || !nameToks.length) continue;

    // Count how many name tokens appear in note tokens (substring match)
    const hits = nameToks.filter(nt => noteToks.some(no => no.includes(nt) || nt.includes(no))).length;
    const sim = hits / nameToks.length;
    if (sim > best) best = sim;
  }
  return best;
}

function matchSquareToEntries(txn, entries) {
  const amt = (txn.amount_money?.amount || 0) / 100;
  const note = txn.note || '';
  const results = [];

  // Detect if note looks like a service description rather than a patient name
  // (contains words like "exam", "copay", "myopia", "contact", "optomap", "pay")
  const svcKeywords = /\b(exam|copay|myopia|contact|optomap|general|private|control|lens|pay)\b/i;
  const noteIsServiceDesc = svcKeywords.test(note);

  for (const e of entries) {
    const alreadyLinked = e.squareTransactionId === txn.id ||
      (Array.isArray(e.squareTransactionIds) && e.squareTransactionIds.includes(txn.id));
    if (alreadyLinked) return [{entry: e, score: 2.0, amtMatch: true, nameSim: 1, alreadyLinked: true}];

    const ptPaid = parseFloat(e.ptPaid) || 0;
    const svcTotal = ['exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherAmt2']
      .reduce((s,k) => s + (parseFloat(e[k])||0), 0);
    const disc = parseFloat(e.discountAmount)||0;
    const expectedPt = Math.max(0, svcTotal - disc);

    const amtMatchPaid   = amt > 0 && ptPaid > 0 && Math.abs(amt - ptPaid) < 1.0;
    const amtMatchExpect = amt > 0 && expectedPt > 0 && Math.abs(amt - expectedPt) < 1.0;
    const amtMatch       = amtMatchPaid || amtMatchExpect;
    const isZero         = amt === 0;

    // Name match — skip if note is a service description
    const nameSim = (!noteIsServiceDesc && note) ? squareNameSim(note, e.patientName) : 0;

    // Scoring: name match is primary signal, amount is secondary
    // $0 transactions: match by name only
    const score = isZero
      ? nameSim
      : (nameSim * 0.55) + (amtMatch ? 0.45 : 0);

    if (nameSim >= 0.4 || (amtMatch && score > 0.2)) {
      results.push({entry: e, score, amtMatch, nameSim, alreadyLinked: false});
    }
  }
  return results.sort((a,b) => b.score - a.score);
}

function fmtFill(n) {
  const s = n.toFixed(2);
  return s.endsWith('.00') ? String(Math.round(n)) : s;
}

function buildFills(lineItems, examFee) {
  const fills = {};
  let hasOther = false, hasOther2 = false;
  let totalDiscount = 0;
  for (const item of (lineItems||[])) {
    const name = item.name || '';
    const baseAmt = (item.base_price_money?.amount||0) / 100 * (item.quantity||1);
    const totalAmt = item.total_money ? (item.total_money.amount||0) / 100 : baseAmt;
    const discAmt = Math.max(0, baseAmt - totalAmt);
    if (discAmt > 0) totalDiscount += discAmt;
    const amt = baseAmt; // keep base price for service fields
    const map = getSquareItemMapping(name);
    if (!map) continue;
    if (map.split === 'exam_cl') {
      fills.exam = fmtFill(examFee||89);
      fills.cl   = fmtFill(Math.max(0, amt - (examFee||89)));
    } else if (map.split === 'optos_oct') {
      if (amt === 74 || amt === 75) {
        fills.oct   = fmtFill(35);
        fills.optos = fmtFill(amt - 35);
      } else {
        fills.optos = fmtFill(amt);
      }
    } else if (map.col === 'otherAmt') {
      if (!hasOther) { fills.otherAmt=fmtFill(amt); fills.otherType=map.otherType||''; hasOther=true; }
      else if (!hasOther2) { fills.otherAmt2=fmtFill(amt); fills.otherType2=map.otherType||''; hasOther2=true; }
    } else {
      fills[map.col] = fmtFill(amt);
    }
  }
  return {fills, totalDiscount};
}




function SquarePanel({date, loc, entries, onEntryUpdated, onSave, feeSettings}) {
  const [txns, setTxns]             = React.useState(null);
  const [loading, setLoading]       = React.useState(false);
  const [error, setError]           = React.useState('');
  const [approving, setApproving]   = React.useState({});
  const [overrides, setOverrides]   = React.useState({});
  const [open, setOpen]             = React.useState(false);
  const [conflicts, setConflicts]   = React.useState(null);
  const [squareNotes, setSquareNotes] = React.useState({});
  const [splitTxn, setSplitTxn]     = React.useState(null);
  const [splitAmounts, setSplitAmounts] = React.useState({});
  const [splitSaving, setSplitSaving] = React.useState(false);

  const examFee = parseFloat(feeSettings?.examFee) || 89;

  const load = async () => {
    if (loading) return;
    setLoading(true); setError('');
    try {
      // Load doctor notes/prematches alongside transactions
      const { getDocs, collection, query, where } = await import('firebase/firestore');
      const notesSnap = await getDocs(query(collection(db,'squareNotes'), where('date','==',date||'')));
      const notesMap = {};
      notesSnap.docs.forEach(d=>{notesMap[d.data().txnId]={note:d.data().note||'',preMatch:d.data().preMatch||''};});
      setSquareNotes(notesMap);

      const res = await fetch(SQUARE_WORKER, {
        method: 'POST',
        headers: {'Content-Type':'application/json'},
        body: JSON.stringify({begin_time:`${date}T00:00:00-07:00`, end_time:`${date}T23:59:59-07:00`, _t: Date.now()})
      });
      if (!res.ok) throw new Error(`Worker error ${res.status}`);
      const data = await res.json();
      const payments = (data.payments||[])
        .filter(p => (p.status==='COMPLETED'||p.status==='REFUNDED') && deviceToLoc(p.device_details?.device_name)===loc)
        .sort((a,b)=>(a.created_at||'').localeCompare(b.created_at||''));
      setTxns(payments);
    } catch(e) { setError(e.message); }
    finally { setLoading(false); }
  };

  // Use standalone buildFills
  const buildFillsForTxn = (txn) => { const {fills,totalDiscount} = buildFills(txn.line_items, examFee); if(totalDiscount>0) fills.discountAmount=String(Math.round(totalDiscount*100)/100); return fills; };

  // Check if any fills conflict with existing non-zero values
  const checkConflicts = (entry, fills) => {
    const skipFields = new Set(['squareTransactionId','squareTransactionIds','squareApprovedAt','ptPaid','cashStatus']);
    return Object.keys(fills).filter(k => {
      if (k === 'otherType' || k === 'otherType2') return false;
      if (skipFields.has(k)) return false;
      const existing = parseFloat(entry[k]);
      const incoming = parseFloat(fills[k]);
      return existing > 0 && Math.abs(existing - incoming) > 0.01;
    });
  };

  const doLinkOnly = async (txn, entry) => {
    const key = txn.id;
    setApproving(p=>({...p,[key]:true}));
    try {
      const {setDoc,doc:fdoc} = await import('firebase/firestore');
      const existingIds = Array.isArray(entry.squareTransactionIds)
        ? entry.squareTransactionIds
        : entry.squareTransactionId ? [entry.squareTransactionId] : [];
      const squareTransactionIds = existingIds.includes(txn.id) ? existingIds : [...existingIds, txn.id];
      const upd = {...entry,
        squareTransactionId: txn.id,
        squareTransactionIds,
        updatedAt: new Date().toISOString()
      };
      await setDoc(fdoc(db,'billingEntries',entry.id), upd);
      onEntryUpdated(upd);
      onSave(upd);
    } catch(e) { alert('Link failed: '+e.message); }
    setApproving(p=>({...p,[key]:false}));
  };

  const doSplitSquare = async () => {
    if (!splitTxn) return;
    const total = (splitTxn.amount_money?.amount||0)/100;
    const assigned = Object.values(splitAmounts).reduce((s,v)=>s+(parseFloat(v)||0),0);
    if (Math.abs(assigned - total) > 0.01) {
      alert(`Amounts must add up to ${fmt$(total)}. Currently: ${fmt$(assigned)}`); return;
    }
    setSplitSaving(true);
    try {
      const {setDoc, doc: fsDoc} = await import('firebase/firestore');
      for (const [entryId, amtStr] of Object.entries(splitAmounts)) {
        const amt = parseFloat(amtStr)||0;
        if (amt <= 0) continue;
        const entry = entries.find(e=>e.id===entryId);
        if (!entry) continue;
        const existingIds = Array.isArray(entry.squareTransactionIds)
          ? entry.squareTransactionIds
          : entry.squareTransactionId ? [entry.squareTransactionId] : [];
        const squareTransactionIds = existingIds.includes(splitTxn.id) ? existingIds : [...existingIds, splitTxn.id];
        const upd = {...entry,
          ptPaid: String(amt.toFixed(2)),
          squareTransactionId: splitTxn.id,
          squareTransactionIds,
          updatedAt: new Date().toISOString()
        };
        const clean = Object.fromEntries(Object.entries(upd).filter(([,v])=>v!==undefined));
        await setDoc(fsDoc(db,'billingEntries',entryId), clean);
        onEntryUpdated(clean);
        if (onSave) onSave(clean);
      }
      setSplitTxn(null); setSplitAmounts({});
    } catch(e) { alert('Split failed: '+e.message); }
    setSplitSaving(false);
  };

  const doWrite = async (txn, entry, fills) => {
    const key = txn.id;
    setApproving(p=>({...p,[key]:true}));
    try {
      const amt = (txn.amount_money?.amount||0)/100;
      const isCash = txn.source_type === 'CASH';
      // Store all linked transaction IDs as array
      const existingIds = Array.isArray(entry.squareTransactionIds)
        ? entry.squareTransactionIds
        : entry.squareTransactionId ? [entry.squareTransactionId] : [];
      const squareTransactionIds = existingIds.includes(txn.id)
        ? existingIds
        : [...existingIds, txn.id];
      const merged = {...entry, ...fills};
      const ptPaidComputed = ['exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherAmt2']
        .reduce((s,k)=>s+(parseFloat(merged[k])||0),0)-(parseFloat(merged.discountAmount)||0);
      const upd = {
        ...merged,
        squareTransactionId: txn.id,
        squareTransactionIds,
        ptPaid: String(Math.max(0, ptPaidComputed)),
        squareApprovedAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      if (isCash && amt > 0) upd.cashStatus = 'expected';
      const {setDoc, doc: fsDoc} = await import('firebase/firestore');
      await setDoc(fsDoc(db,'billingEntries',entry.id), upd);
      onEntryUpdated(upd);
      if (onSave) onSave(upd);
      // Force panel to re-evaluate matches with updated entry data
      setTxns(prev => prev ? [...prev] : prev);
    } catch(e) { alert('Error saving: '+e.message); }
    finally { setApproving(p=>({...p,[key]:false})); }
  };

  const handleWrite = (txn, entry) => {
    const fills = buildFillsForTxn(txn);
    // Always write ptPaid from transaction total if no line items mapped ptPaid
    if (!fills.ptPaid) {
      const amt = (txn.amount_money?.amount||0)/100;
      if (amt > 0) fills.ptPaid = String(amt.toFixed(2));
    }
    const conflictFields = checkConflicts(entry, fills);
    if (conflictFields.length > 0) {
      setConflicts({
        txnId: txn.id,
        entry,
        fills,
        conflictFields,
        onConfirm: () => { setConflicts(null); doWrite(txn, entry, fills); },
        onLinkOnly: () => { setConflicts(null); doLinkOnly(txn, entry); },
        onCancel: () => setConflicts(null),
      });
    } else {
      doWrite(txn, entry, fills);
    }
  };

  const locEntries = [...entries].filter(e=>e.date===date&&e.location===loc).sort((a,b)=>(a.sortOrder??9999)-(b.sortOrder??9999));
  const getTxnNote = (txn) => txn.note || txn.tender?.[0]?.note || '';

  if (!open) return (
    <button onClick={()=>{setOpen(true);load();}}
      style={{background:'#F0FDF4',border:'1px solid #6EE7B7',borderRadius:6,padding:'5px 12px',cursor:'pointer',fontSize:11,fontWeight:600,color:'#065F46',display:'inline-flex',alignItems:'center',gap:4}}>
      💳 Square Payments
    </button>
  );

  return (
    <div style={{marginBottom:10,background:'#F8FFFE',border:'1px solid #6EE7B7',borderRadius:8,padding:'10px 12px'}}>
      {/* Conflict modal */}
      {conflicts&&(
        <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',zIndex:2000,display:'flex',alignItems:'center',justifyContent:'center'}}>
          <div style={{background:'white',borderRadius:12,padding:20,maxWidth:380,width:'90%',boxShadow:'0 8px 40px rgba(0,0,0,0.2)'}}>
            <h4 style={{fontFamily:"'DM Serif Display',serif",fontSize:14,color:'#1B3A5C',marginBottom:8}}>Overwrite existing values?</h4>
            <p style={{fontSize:11,color:'#64748B',marginBottom:10}}>
              These fields already have values that differ from Square:
            </p>
            {conflicts.conflictFields.map(f=>(
              <div key={f} style={{display:'flex',justifyContent:'space-between',fontSize:11,padding:'3px 8px',background:'#FEF3C7',borderRadius:4,marginBottom:3}}>
                <span style={{fontWeight:600}}>{f}</span>
                <span style={{color:'#94A3B8'}}>existing: {conflicts.entry[f]} → Square: {conflicts.fills[f]}</span>
              </div>
            ))}
            <div style={{display:'flex',gap:8,marginTop:14,justifyContent:'flex-end'}}>
              <button onClick={conflicts.onCancel} style={{background:'#F1F5F9',border:'none',borderRadius:6,padding:'6px 14px',cursor:'pointer',fontSize:11,color:'#64748B'}}>Cancel</button>
              <button onClick={conflicts.onLinkOnly} style={{background:'#EFF6FF',border:'1px solid #BFDBFE',borderRadius:6,padding:'6px 14px',cursor:'pointer',fontSize:11,color:'#1D4ED8',fontWeight:600}}>Link Only</button>
              <button onClick={conflicts.onConfirm} style={{background:'#1B3A5C',color:'white',border:'none',borderRadius:6,padding:'6px 14px',cursor:'pointer',fontSize:11,fontWeight:700}}>Overwrite</button>
            </div>
          </div>
        </div>
      )}

      {/* Split Modal */}
      {splitTxn&&(()=>{
        const total=(splitTxn.amount_money?.amount||0)/100;
        const assigned=Object.values(splitAmounts).reduce((s,v)=>s+(parseFloat(v)||0),0);
        const remaining=Math.max(0,total-assigned);
        const dayPts=entries.filter(e=>e.patientName?.trim()&&e.date===date&&e.location===loc&&e.patientName!=='— Store Closed —');
        const addedIds=Object.keys(splitAmounts);
        const unadded=dayPts.filter(e=>!addedIds.includes(e.id));
        return (
          <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',zIndex:2000,display:'flex',alignItems:'center',justifyContent:'center'}}>
            <div style={{background:'white',borderRadius:12,padding:20,maxWidth:440,width:'90%',boxShadow:'0 8px 40px rgba(0,0,0,0.2)'}} onClick={e=>e.stopPropagation()}>
              <h4 style={{fontFamily:"'DM Serif Display',serif",fontSize:14,color:'#1B3A5C',marginBottom:4}}>Split Payment</h4>
              <p style={{fontSize:11,color:'#64748B',marginBottom:12}}>
                Total: <strong>{fmt$(total)}</strong> · Remaining: <strong style={{color:Math.abs(remaining)<0.01?'#16A34A':'#DC2626'}}>{fmt$(remaining)}</strong>
              </p>

              {/* Added patients */}
              {addedIds.map(id=>{
                const pt=dayPts.find(e=>e.id===id);
                if(!pt) return null;
                return (
                  <div key={id} style={{display:'flex',alignItems:'center',gap:8,marginBottom:8}}>
                    <button onClick={()=>setSplitAmounts(p=>{const n={...p};delete n[id];return n;})}
                      style={{background:'none',border:'none',color:'#DC2626',cursor:'pointer',fontSize:12,padding:0}}>✕</button>
                    <span style={{fontSize:11,flex:1,color:'#1B3A5C',fontWeight:600}}>{pt.patientName}</span>
                    <span style={{fontSize:9,color:'#94A3B8'}}>{pt.payor1||'Self'}</span>
                    <input type="text" inputMode="decimal"
                      value={splitAmounts[id]||''}
                      onChange={ev=>setSplitAmounts(p=>({...p,[id]:ev.target.value}))}
                      placeholder="0.00"
                      autoFocus={addedIds[addedIds.length-1]===id}
                      style={{width:70,border:'1.5px solid #BAE6FD',borderRadius:5,padding:'4px 6px',fontSize:11,textAlign:'right'}}/>
                  </div>
                );
              })}

              {/* Add patient dropdown */}
              {unadded.length>0&&(
                <div style={{marginBottom:12}}>
                  <select value="" onChange={e=>{
                      const id=e.target.value;
                      if(id){ setSplitAmounts(p=>({...p,[id]:''})); }
                    }}
                    style={{width:'100%',border:'1px solid #E2E8F0',borderRadius:6,padding:'5px 8px',fontSize:11,color:'#64748B'}}>
                    <option value="" disabled>+ Add patient...</option>
                    {unadded.map(pt=><option key={pt.id} value={pt.id}>{pt.patientName} {pt.payor1?`(${pt.payor1})`:''}</option>)}
                  </select>
                </div>
              )}

              {addedIds.length===0&&<p style={{fontSize:11,color:'#94A3B8',fontStyle:'italic',marginBottom:12}}>Select patients above to assign amounts</p>}

              <div style={{display:'flex',justifyContent:'space-between',fontSize:11,color:'#64748B',marginBottom:12,paddingTop:8,borderTop:'1px solid #F0F4F8'}}>
                <span>Assigned: {fmt$(assigned)} / {fmt$(total)}</span>
                <span style={{color:Math.abs(assigned-total)<0.01?'#16A34A':'#94A3B8'}}>{Math.abs(assigned-total)<0.01?'✓ Balanced':'not balanced'}</span>
              </div>
              <div style={{display:'flex',gap:8,justifyContent:'flex-end'}}>
                <button onClick={()=>{setSplitTxn(null);setSplitAmounts({});}} style={{background:'#F1F5F9',border:'none',borderRadius:6,padding:'6px 12px',cursor:'pointer',fontSize:11,color:'#64748B'}}>Cancel</button>
                <button onClick={doSplitSquare} disabled={splitSaving||Math.abs(assigned-total)>0.01||addedIds.length===0}
                  style={{background:Math.abs(assigned-total)<0.01&&addedIds.length>0?'#1B3A5C':'#94A3B8',color:'white',border:'none',borderRadius:6,padding:'6px 16px',cursor:'pointer',fontSize:11,fontWeight:700}}>
                  {splitSaving?'Saving...':'✓ Apply Split'}
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      <div style={{display:'flex',alignItems:'center',gap:6,marginBottom:8}}>
        <span style={{fontSize:11,fontWeight:700,color:'#065F46'}}>💳 Square — {date} {loc}</span>
        <button onClick={load} disabled={loading} style={{background:'#F0FDF4',border:'1px solid #6EE7B7',borderRadius:4,padding:'2px 8px',cursor:'pointer',fontSize:9,color:'#065F46'}}>{loading?'...':'↺'}</button>
        <button onClick={()=>setOpen(false)} style={{marginLeft:'auto',background:'none',border:'none',cursor:'pointer',fontSize:12,color:'#94A3B8'}}>✕</button>
      </div>

      {error&&<div style={{fontSize:10,color:'#DC2626',marginBottom:6}}>Error: {error}</div>}
      {loading&&<div style={{fontSize:10,color:'#94A3B8'}}>Loading...</div>}
      {txns&&txns.length===0&&<div style={{fontSize:10,color:'#94A3B8'}}>No completed transactions for {loc} on {date}.</div>}

      {txns&&txns.map(txn=>{
        const amt = (txn.amount_money?.amount||0)/100;
        const note = getTxnNote(txn);
        const time = fmtTime(txn.created_at);
        const isCash = txn.source_type==='CASH';
        const isRefunded = txn.status==='REFUNDED';
        const overrideId = overrides[txn.id];
        const docNoteData = squareNotes[txn.id]||{};
        const docNote = docNoteData.note;
        const docPreMatch = docNoteData.preMatch;
        const matches = matchSquareToEntries({...txn,note}, locEntries);
        // Boost score if doctor pre-matched this transaction to a patient name
        const boostedMatches = docPreMatch
          ? locEntries.map(e=>({entry:e,score:e.patientName===docPreMatch?1.5:(matches.find(m=>m.entry.id===e.id)?.score||0)})).filter(m=>m.score>0).sort((a,b)=>b.score-a.score)
          : matches;
        const best = overrideId ? locEntries.find(e=>e.id===overrideId) : boostedMatches[0]?.entry;
        const alreadyLinked = best?.squareTransactionId===txn.id ||
          (Array.isArray(best?.squareTransactionIds) && best.squareTransactionIds.includes(txn.id));
        const isApproving = approving[txn.id];
        const lineItems = txn.line_items||[];
        const fills = buildFillsForTxn(txn);
        const hasMappedItems = Object.keys(fills).length > 0;

        const bestScore = matches[0]?.score||0;
        const confidence = alreadyLinked?'linked':bestScore>=0.9?'high':bestScore>=0.5?'med':best?'low':'none';
        const confColor = {linked:'#065F46',high:'#16A34A',med:'#92400E',low:'#64748B',none:'#DC2626'}[confidence];
        const confBg    = {linked:'#F0FDF4',high:'#DCFCE7',med:'#FEF3C7',low:'#F8FAFC',none:'#FEF2F2'}[confidence];

        return (
          <div key={txn.id} style={{marginBottom:3,padding:'3px 6px',background:confBg,borderRadius:4,border:`1px solid ${confColor}40`}}>
            <div style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap'}}>
              <span style={{fontSize:10,fontWeight:700,color:'#1B3A5C',whiteSpace:'nowrap'}}
                title={(()=>{
                  const card=txn.card_details?.card;
                  const parts=[];
                  if(card?.cardholder_name) parts.push(card.cardholder_name);
                  if(card?.card_brand&&card?.last_4) parts.push(`${card.card_brand} ••••${card.last_4}`);
                  if(isCash) parts.push('Cash');
                  if(txn.buyer_email_address) parts.push(txn.buyer_email_address);
                  return parts.join(' · ')||'';
                })()}>{fmt$(amt)}</span>
              <span style={{fontSize:9,color:'#94A3B8',whiteSpace:'nowrap'}}>{time}</span>
              {isCash&&amt>0&&<span style={{fontSize:8,background:'#FEF3C7',color:'#92400E',borderRadius:2,padding:'0 3px',fontWeight:700}}>CASH</span>}
              {isCash&&amt>0&&!isRefunded&&(()=>{
                const txnTime=new Date(txn.created_at).getTime();
                const dupCard=(txns||[]).find(t=>
                  t.id!==txn.id &&
                  t.source_type!=='CASH' &&
                  t.status==='COMPLETED' &&
                  Math.abs((t.amount_money?.amount||0)/100 - amt) < 0.01 &&
                  Math.abs(new Date(t.created_at).getTime() - txnTime) < 5*60*1000
                );
                return dupCard ? <span title={`Possible duplicate — card transaction of ${fmt$(amt)} exists at ${fmtTime(dupCard.created_at)}`} style={{fontSize:8,background:'#FEE2E2',color:'#DC2626',borderRadius:2,padding:'0 3px',fontWeight:700}}>⚠ Duplicate?</span> : null;
              })()}
              {isRefunded&&<span style={{fontSize:8,background:'#F0FDF4',color:'#16A34A',borderRadius:2,padding:'0 3px',fontWeight:700}}>✓ Refunded</span>}
              {amt===0&&<span style={{fontSize:8,background:'#F1F5F9',color:'#94A3B8',borderRadius:2,padding:'0 3px',fontWeight:700}}>$0</span>}
              {lineItems.length>0&&(
                <div style={{marginTop:2}}>
                  {lineItems.flatMap((item,ii)=>{
                    const m=getSquareItemMapping(item.name);
                    const qty=parseInt(item.quantity||1);
                    const unitAmt=(item.base_price_money?.amount||0)/100;
                    const totalAmt=item.total_money?(item.total_money.amount||0)/100:(unitAmt*qty);
                    const discAmt=Math.max(0,unitAmt*qty-totalAmt);
                    const itemNote=item.note||item.variation_name||'';
                    const label=m?(m.col==='otherAmt'?m.otherType||'other':m.col):item.name||'item';
                    if(qty>1){
                      return Array.from({length:qty},(_,i)=>(
                        <div key={`${ii}-${i}`} style={{fontSize:9,color:'#64748B',display:'flex',gap:4,alignItems:'center'}}>
                          <span style={{color:'#475569',fontWeight:600}}>{label}: {fmt$(unitAmt)}</span>
                          {itemNote&&<span style={{color:'#0891B2',fontStyle:'italic'}}>"{itemNote}"</span>}
                        </div>
                      ));
                    }
                    return [(
                      <div key={ii} style={{fontSize:9,color:'#64748B',display:'flex',gap:4,alignItems:'center'}}>
                        <span style={{color:'#475569',fontWeight:600}}>{label}: {fmt$(totalAmt)}{discAmt>0?` (-${fmt$(discAmt)})`:''}</span>
                        {itemNote&&<span style={{color:'#0891B2',fontStyle:'italic'}}>"{itemNote}"</span>}
                      </div>
                    )];
                  })}
                </div>
              )}
              {note&&<span style={{fontSize:9,color:'#475569',fontStyle:'italic',whiteSpace:'nowrap',maxWidth:130,overflow:'hidden',textOverflow:'ellipsis'}}>"{note}"</span>}
              {docPreMatch&&!alreadyLinked&&<span style={{fontSize:8,background:'#EFF6FF',color:'#1D4ED8',borderRadius:3,padding:'0 4px',fontWeight:700,whiteSpace:'nowrap'}} title="Pre-matched by doctor">👨‍⚕️ {docPreMatch}</span>}
              {docNote&&<span style={{fontSize:8,background:'#FFFBEB',color:'#92400E',borderRadius:3,padding:'0 4px',whiteSpace:'nowrap'}} title={docNote}>📝 Dr note</span>}
              <select
                value={overrideId||best?.id||''}
                onChange={e=>setOverrides(p=>({...p,[txn.id]:e.target.value}))}
                style={{fontSize:10,padding:'1px 3px',border:'1px solid #E2E8F0',borderRadius:3,background:'white',fontFamily:"'DM Sans',sans-serif",maxWidth:130,flexShrink:0}}>
                {!best&&<option value="">— Patient —</option>}
                {[...(best?[best]:[]),...locEntries.filter(e=>e.id!==best?.id)].map(e=>(
                  <option key={e.id} value={e.id}>{e.patientName}</option>
                ))}
              </select>
              {alreadyLinked?(
                <><span style={{fontSize:10,color:'#065F46',fontWeight:700}}>💳</span>
                <button onClick={async()=>{
                  const entry=locEntries.find(e=>e.squareTransactionId===txn.id||(Array.isArray(e.squareTransactionIds)&&e.squareTransactionIds.includes(txn.id)));
                  if(!entry) return;
                  if(!window.confirm(`Unlink Square transaction from ${entry.patientName} and reset service fields?`)) return;
                  const {setDoc,doc:fsDoc}=await import('firebase/firestore');
                  const upd={...entry,squareTransactionId:'',squareTransactionIds:[],exam:'',cl:'',optos:'',oct:'',dfe:'',ov:'',otherAmt:'',otherAmt2:'',discountAmount:'',ptPaid:'',updatedAt:new Date().toISOString()};
                  const clean=Object.fromEntries(Object.entries(upd).filter(([,v])=>v!==undefined));
                  await setDoc(fsDoc(db,'billingEntries',entry.id),clean);
                  onEntryUpdated(clean);if(onSave)onSave(clean);
                  setTxns(prev=>prev?[...prev]:prev);
                }} style={{background:'#FEE2E2',border:'none',borderRadius:3,padding:'1px 6px',cursor:'pointer',fontSize:9,color:'#DC2626',fontWeight:700}}>Unlink</button></>
              ):(best||overrideId)?(
                <button
                  onClick={()=>handleWrite(txn, locEntries.find(e=>e.id===(overrideId||best?.id))||best)}
                  disabled={isApproving}
                  style={{background:isApproving?'#94A3B8':'#065F46',color:'white',border:'none',borderRadius:3,padding:'2px 8px',cursor:'pointer',fontSize:10,fontWeight:700,whiteSpace:'nowrap',flexShrink:0}}>
                  {isApproving?'...':'✓ Write'}
                </button>
              ):null}
              {/* Split button — always show for unlinked transactions with multiple patients */}
              {!alreadyLinked&&locEntries.filter(e=>e.patientName?.trim()).length>1&&(
                <button onClick={()=>{
                  const pts=locEntries.filter(e=>e.patientName?.trim());
                  const total=(txn.amount_money?.amount||0)/100;
                  setSplitAmounts({});setSplitTxn(txn);
                }} style={{background:'#EFF6FF',color:'#1D4ED8',border:'1px solid #BFDBFE',borderRadius:3,padding:'2px 8px',cursor:'pointer',fontSize:10,whiteSpace:'nowrap'}}>
                  Split
                </button>
              )}
              {/* → Reconcile and Dismiss — only show if not already linked */}
              {!alreadyLinked&&(
                <>
                  <button onClick={async()=>{
                    const {setDoc,doc:fsDoc}=await import('firebase/firestore');
                    await setDoc(fsDoc(db,'squarePending',`sq_${txn.id}`),{
                      txnId:txn.id, amount:amt, date, loc, note:getTxnNote(txn),
                      lineItems:txn.line_items||[], sourceType:txn.source_type||'',
                      suggestedEntryId:best?.id||null,
                      status:'pending', savedAt:new Date().toISOString()
                    });
                    // Remove from current panel view
                    setTxns(prev=>prev?prev.filter(t=>t.id!==txn.id):prev);
                  }} style={{background:'#EFF6FF',border:'1px solid #BFDBFE',borderRadius:3,padding:'2px 7px',cursor:'pointer',fontSize:9,color:'#1D4ED8',whiteSpace:'nowrap',flexShrink:0}}>
                    → Reconcile
                  </button>
                  <button onClick={async()=>{
                    const reason=window.prompt('Dismiss reason (optional):')||'';
                    const {setDoc,doc:fsDoc}=await import('firebase/firestore');
                    await setDoc(fsDoc(db,'squarePending',`sq_${txn.id}`),{
                      txnId:txn.id, amount:amt, date, loc, note:getTxnNote(txn),
                      status:'dismissed', dismissReason:reason, dismissedAt:new Date().toISOString()
                    });
                    setTxns(prev=>prev?prev.filter(t=>t.id!==txn.id):prev);
                  }} style={{background:'#FEF2F2',border:'1px solid #FECACA',borderRadius:3,padding:'2px 7px',cursor:'pointer',fontSize:9,color:'#DC2626',whiteSpace:'nowrap',flexShrink:0}}>
                    Dismiss
                  </button>
                </>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── Days tab ────────────────────────────────────────────────────────────────
// ── Doctor Log Panel (admin view on entry page) ──────────────────────────────
// ── Match Payments Panel ──────────────────────────────────────────────────────
function MatchPaymentsPanel({date, loc, entries, doctorLogs, onEntryUpdated, onSave, feeSettings, onClose}) {
  const [txns, setTxns] = React.useState(null);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState('');
  const [approving, setApproving] = React.useState({});
  const [overrides, setOverrides] = React.useState({}); // txnId -> entryId
  const [squareNotes, setSquareNotes] = React.useState({});
  const [doneMatching, setDoneMatching] = React.useState(false);
  const [splitTxn, setSplitTxn] = React.useState(null); // txn being split
  const [splitAmounts, setSplitAmounts] = React.useState({}); // entryId -> amount string
  const [splitSaving, setSplitSaving] = React.useState(false);
  const examFee = parseFloat(feeSettings?.examFee) || 89;

  const locEntries = entries.filter(e => e.date === date && e.location === loc)
    .sort((a,b)=>(a.sortOrder??9999)-(b.sortOrder??9999));
  const locDoctorLogs = (doctorLogs||[]).filter(l => l.date === date && (!loc || l.location === loc));

  React.useEffect(() => { loadData(); }, []); // eslint-disable-line

  const doSplit = async () => {
    if (!splitTxn) return;
    const total = (splitTxn.amount_money?.amount||0)/100;
    const assigned = Object.values(splitAmounts).reduce((s,v)=>s+(parseFloat(v)||0),0);
    if (Math.abs(assigned - total) > 0.01) {
      alert(`Amounts must add up to ${fmt$(total)}. Currently: ${fmt$(assigned)}`);
      return;
    }
    setSplitSaving(true);
    try {
      const {setDoc,doc:fdoc} = await import('firebase/firestore');
      for (const [entryId, amtStr] of Object.entries(splitAmounts)) {
        const amt = parseFloat(amtStr)||0;
        if (amt <= 0) continue;
        const entry = locEntries.find(e=>e.id===entryId);
        if (!entry) continue;
        const existingIds = Array.isArray(entry.squareTransactionIds)
          ? entry.squareTransactionIds
          : entry.squareTransactionId ? [entry.squareTransactionId] : [];
        const squareTransactionIds = existingIds.includes(splitTxn.id) ? existingIds : [...existingIds, splitTxn.id];
        const upd = {...entry,
          ptPaid: String(amt.toFixed(2)),
          squareTransactionId: splitTxn.id,
          squareTransactionIds,
          updatedAt: new Date().toISOString()
        };
        await setDoc(fdoc(db,'billingEntries',entryId), upd);
        onEntryUpdated(upd);
        onSave(upd);
      }
      setSplitTxn(null);
      setSplitAmounts({});
    } catch(e) { alert('Split failed: '+e.message); }
    setSplitSaving(false);
  };


  const loadData = async () => {
    setLoading(true); setError('');
    try {
      const { getDocs, collection, query, where } = await import('firebase/firestore');
      const notesSnap = await getDocs(query(collection(db,'squareNotes'), where('date','==',date||'')));
      const notesMap = {};
      notesSnap.docs.forEach(d => { notesMap[d.data().txnId] = {note:d.data().note||'', preMatch:d.data().preMatch||''}; });
      setSquareNotes(notesMap);

      const res = await fetch(SQUARE_WORKER, {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({begin_time:`${date}T00:00:00-07:00`, end_time:`${date}T23:59:59-07:00`, _t:Date.now()})
      });
      if (!res.ok) throw new Error(`Worker error ${res.status}`);
      const data = await res.json();
      setTxns((data.payments||[])
        .filter(p => (p.status==='COMPLETED'||p.status==='REFUNDED') && deviceToLoc(p.device_details?.device_name)===loc)
        .sort((a,b) => (a.created_at||'').localeCompare(b.created_at||'')));
    } catch(e) { setError(e.message); }
    setLoading(false);
  };

  const doWrite = async (txn, entry) => {
    const key = txn.id;
    setApproving(p=>({...p,[key]:true}));
    try {
      const {fills,totalDiscount} = buildFills(txn.line_items, examFee);
      if(totalDiscount>0) fills.discountAmount=String(Math.round(totalDiscount*100)/100);
      const amt = (txn.amount_money?.amount||0)/100;
      if (!fills.ptPaid && amt > 0) fills.ptPaid = String(amt.toFixed(2));
      const existingIds = Array.isArray(entry.squareTransactionIds)
        ? entry.squareTransactionIds
        : entry.squareTransactionId ? [entry.squareTransactionId] : [];
      const squareTransactionIds = existingIds.includes(txn.id) ? existingIds : [...existingIds, txn.id];
      const merged = {...entry, ...fills};
      const ptPaidComputed = ['exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherAmt2']
        .reduce((s,k)=>s+(parseFloat(merged[k])||0),0)-(parseFloat(merged.discountAmount)||0);
      const upd = {
        ...merged,
        squareTransactionId: txn.id, squareTransactionIds,
        ptPaid: String(Math.max(0, ptPaidComputed)),
        squareApprovedAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      if (txn.source_type==='CASH' && amt > 0) upd.cashStatus = 'expected';
      const {setDoc, doc: fsDoc} = await import('firebase/firestore');
      await setDoc(fsDoc(db,'billingEntries',entry.id), upd);
      onEntryUpdated(upd);
      if (onSave) onSave(upd);
      setTxns(prev => prev ? [...prev] : prev);
    } catch(e) { alert('Error: '+e.message); }
    finally { setApproving(p=>({...p,[key]:false})); }
  };

  const sendToReconcile = async (txn) => {
    const {setDoc, doc: fsDoc} = await import('firebase/firestore');
    const amt = (txn.amount_money?.amount||0)/100;
    await setDoc(fsDoc(db,'squarePending',`sq_${txn.id}`), {
      txnId: txn.id,
      amount: amt,
      note: txn.note||'',
      lineItems: txn.line_items||[],
      sourceType: txn.source_type||'',
      date, loc, location: loc,
      savedAt: new Date().toISOString(),
      status: 'pending',
    });
    setTxns(prev => prev ? prev.filter(t => t.id !== txn.id) : prev);
  };

  // Build unified time-ordered rows
  const rows = React.useMemo(() => {
    if (!txns) return [];
    const result = [];
    const usedEntryIds = new Set();
    const usedLogIds = new Set();

    // For each Square txn, find best matching entry and doctor log
    txns.forEach(txn => {
      const note = txn.note || '';
      const docNote = squareNotes[txn.id];
      const preMatchName = docNote?.preMatch || '';

      // Match billing entry
      const entryMatch = locEntries
        .map(e => ({e, score: preMatchName && e.patientName===preMatchName ? 1.5 : squareNameSim(note, e.patientName)}))
        .filter(m => m.score > 0.3)
        .sort((a,b) => b.score - a.score)[0]?.e;

      const overrideEntry = overrides[txn.id] ? locEntries.find(e=>e.id===overrides[txn.id]) : null;
      const linkedEntry = overrideEntry || entryMatch;

      // Match doctor log — use linked entry's patient name if available (handles manual overrides)
      const matchName = linkedEntry?.patientName || note;
      const logMatch = locDoctorLogs
        .filter(l => !usedLogIds.has(l.id))
        .map(l => ({l, score: squareNameSim(matchName, l.patientName)}))
        .filter(m => m.score > 0.3)
        .sort((a,b) => b.score - a.score)[0]?.l;

      if (linkedEntry) usedEntryIds.add(linkedEntry.id);
      if (logMatch) usedLogIds.add(logMatch.id);

      result.push({
        type: 'square',
        txn,
        entry: linkedEntry,
        log: logMatch,
        time: txn.created_at,
        docNote,
      });
    });

    // Add unmatched billing entries
    locEntries.filter(e => !usedEntryIds.has(e.id)).forEach(e => {
      const logMatch = locDoctorLogs.filter(l => !usedLogIds.has(l.id))
        .map(l => ({l, score: squareNameSim(e.patientName, l.patientName)}))
        .filter(m => m.score > 0.5)
        .sort((a,b) => b.score - a.score)[0]?.l;
      if (logMatch) usedLogIds.add(logMatch.id);
      result.push({type:'entry', entry:e, log:logMatch, time:e.createdAt});
    });

    // Add remaining unmatched doctor log entries
    locDoctorLogs.filter(l => !usedLogIds.has(l.id)).forEach(l => {
      result.push({type:'log', log:l, time:l.createdAt});
    });

    return result.sort((a,b) => (a.time||'').localeCompare(b.time||''));
  }, [txns, locEntries, locDoctorLogs, overrides, squareNotes]);

  const colHdr = (text, color) => (
    <div style={{fontSize:9,fontWeight:700,color:color||'#475569',textTransform:'uppercase',marginBottom:6,padding:'4px 0',borderBottom:'2px solid #E2E8F0'}}>{text}</div>
  );

  const cellStyle = (bg) => ({
    background: bg||'white', border:'1px solid #E2E8F0', borderRadius:5,
    padding:'4px 6px', marginBottom:2, minHeight:28, fontSize:11,
  });

  return (
    <div style={{background:'white',border:'1px solid #E2E8F0',borderRadius:10,padding:10,marginBottom:12,boxShadow:'0 2px 12px rgba(0,0,0,0.08)'}}>
      {/* Split Modal */}
      {splitTxn&&(()=>{
        const total=(splitTxn.amount_money?.amount||0)/100;
        const assigned=Object.values(splitAmounts).reduce((s,v)=>s+(parseFloat(v)||0),0);
        const remaining=Math.max(0,total-assigned);
        const dayPts=entries.filter(e=>e.patientName?.trim()&&e.date===date&&e.location===loc&&e.patientName!=='— Store Closed —');
        const addedIds=Object.keys(splitAmounts);
        const unadded=dayPts.filter(e=>!addedIds.includes(e.id));
        return (
          <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',zIndex:2000,display:'flex',alignItems:'center',justifyContent:'center'}}>
            <div style={{background:'white',borderRadius:12,padding:20,maxWidth:440,width:'90%',boxShadow:'0 8px 40px rgba(0,0,0,0.2)'}} onClick={e=>e.stopPropagation()}>
              <h4 style={{fontFamily:"'DM Serif Display',serif",fontSize:14,color:'#1B3A5C',marginBottom:4}}>Split Payment</h4>
              <p style={{fontSize:11,color:'#64748B',marginBottom:12}}>
                Total: <strong>{fmt$(total)}</strong> · Remaining: <strong style={{color:Math.abs(remaining)<0.01?'#16A34A':'#DC2626'}}>{fmt$(remaining)}</strong>
              </p>
              {addedIds.map(id=>{
                const pt=dayPts.find(e=>e.id===id);
                if(!pt) return null;
                return (
                  <div key={id} style={{display:'flex',alignItems:'center',gap:8,marginBottom:8}}>
                    <button onClick={()=>setSplitAmounts(p=>{const n={...p};delete n[id];return n;})}
                      style={{background:'none',border:'none',color:'#DC2626',cursor:'pointer',fontSize:12,padding:0}}>✕</button>
                    <span style={{fontSize:11,flex:1,color:'#1B3A5C',fontWeight:600}}>{pt.patientName}</span>
                    <span style={{fontSize:9,color:'#94A3B8'}}>{pt.payor1||'Self'}</span>
                    <input type="text" inputMode="decimal"
                      value={splitAmounts[id]||''}
                      onChange={ev=>setSplitAmounts(p=>({...p,[id]:ev.target.value}))}
                      placeholder="0.00"
                      style={{width:70,border:'1.5px solid #BAE6FD',borderRadius:5,padding:'4px 6px',fontSize:11,textAlign:'right'}}/>
                  </div>
                );
              })}
              {unadded.length>0&&(
                <div style={{marginBottom:12}}>
                  <select value="" onChange={e=>{
                      const id=e.target.value;
                      if(id){ setSplitAmounts(p=>({...p,[id]:''})); }
                    }}
                    style={{width:'100%',border:'1px solid #E2E8F0',borderRadius:6,padding:'5px 8px',fontSize:11,color:'#64748B'}}>
                    <option value="" disabled>+ Add patient...</option>
                    {unadded.map(pt=><option key={pt.id} value={pt.id}>{pt.patientName} {pt.payor1?`(${pt.payor1})`:''}</option>)}
                  </select>
                </div>
              )}
              {addedIds.length===0&&<p style={{fontSize:11,color:'#94A3B8',fontStyle:'italic',marginBottom:12}}>Select patients above to assign amounts</p>}
              <div style={{display:'flex',justifyContent:'space-between',fontSize:11,color:'#64748B',marginBottom:12,paddingTop:8,borderTop:'1px solid #F0F4F8'}}>
                <span>Assigned: {fmt$(assigned)} / {fmt$(total)}</span>
                <span style={{color:Math.abs(assigned-total)<0.01?'#16A34A':'#94A3B8'}}>{Math.abs(assigned-total)<0.01?'✓ Balanced':'not balanced'}</span>
              </div>
              <div style={{display:'flex',gap:8,justifyContent:'flex-end'}}>
                <button onClick={()=>{setSplitTxn(null);setSplitAmounts({});}} style={{background:'#F1F5F9',border:'none',borderRadius:6,padding:'6px 12px',cursor:'pointer',fontSize:11,color:'#64748B'}}>Cancel</button>
                <button onClick={doSplit} disabled={splitSaving||Math.abs(assigned-total)>0.01||addedIds.length===0}
                  style={{background:Math.abs(assigned-total)<0.01&&addedIds.length>0?'#1B3A5C':'#94A3B8',color:'white',border:'none',borderRadius:6,padding:'6px 16px',cursor:'pointer',fontSize:11,fontWeight:700}}>
                  {splitSaving?'Saving...':'✓ Apply Split'}
                </button>
              </div>
            </div>
          </div>
        );
      })()}
      {/* Header */}
      <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:12}}>
        <span style={{fontFamily:"'DM Serif Display',serif",fontSize:15,color:'#1B3A5C',fontWeight:700}}>💳 Match Payments — {date} {loc}</span>
        <button onClick={loadData} disabled={loading} style={{background:'#F0FDF4',border:'1px solid #6EE7B7',borderRadius:5,padding:'2px 8px',cursor:'pointer',fontSize:10,color:'#065F46'}}>{loading?'...':'↺'}</button>
        <button onClick={onClose} style={{marginLeft:'auto',background:'#F1F5F9',border:'none',borderRadius:6,padding:'4px 10px',cursor:'pointer',fontSize:11,color:'#64748B',fontWeight:600}}>✕ Close</button>
      </div>
      {error&&<div style={{fontSize:11,color:'#DC2626',marginBottom:8}}>Error: {error}</div>}
      {loading&&<div style={{fontSize:11,color:'#94A3B8',marginBottom:8}}>Loading...</div>}

      {/* Three column header */}
      <div style={{display:'grid',gridTemplateColumns:'2fr 1.2fr 1fr',gap:4,marginBottom:4}}>
        {colHdr('💳 Square','#065F46')}
        {colHdr('📝 Doctor Log','#6D28D9')}
        {colHdr('Your Entry','#1B3A5C')}
      </div>

      {/* Rows */}
      {rows.map((row,i) => {
        const txn = row.txn;
        const entry = row.entry;
        const log = row.log;
        const amt = txn ? (txn.amount_money?.amount||0)/100 : 0;
        const time = txn ? fmtTime(txn.created_at) : '';
        const isLinked = txn && entry && (entry.squareTransactionId===txn.id || (Array.isArray(entry.squareTransactionIds)&&entry.squareTransactionIds.includes(txn.id)));
        const isCash = txn?.source_type==='CASH';
        const isApproving = approving[txn?.id];
        const lineItems = txn?.line_items||[];
        const docNoteText = row.docNote?.note;
        const preMatch = row.docNote?.preMatch;
        const overrideId = txn ? overrides[txn.id] : null;

        return (
          <div key={i} style={{display:'grid',gridTemplateColumns:'2fr 1.2fr 1fr',gap:4,marginBottom:2,alignItems:'start'}}>

            {/* Square column — wider */}
            {txn ? (
              <div style={{...cellStyle(isLinked?'#F0FDF4':'white'),border:`1px solid ${isLinked?'#6EE7B7':'#E2E8F0'}`}}>
                {/* Line 1: [dropdown/name · 👨‍⚕️] ←→ [time · $AMT] */}
                <div style={{display:'flex',alignItems:'center',gap:6,marginBottom:3}}>
                  {isLinked
                    ?<span style={{fontSize:11,color:'#065F46',fontWeight:700}}>✓ {entry.patientName}</span>
                    :<div style={{display:'flex',alignItems:'center',gap:4,flex:1,minWidth:0}}>
                      <select value={overrideId||entry?.id||''} onChange={e=>setOverrides(p=>({...p,[txn.id]:e.target.value}))}
                        style={{fontSize:11,padding:'2px 4px',border:'1px solid #E2E8F0',borderRadius:4,background:'white',flex:1,minWidth:0,color:(overrideId||entry?.id)?'#1B3A5C':'#475569'}}>
                        <option value="">— Select patient —</option>
                        {locEntries.map(e=><option key={e.id} value={e.id}>{e.patientName}</option>)}
                      </select>
                      {preMatch&&<span style={{fontSize:10,color:'#1D4ED8',whiteSpace:'nowrap'}} title={`Doctor pre-matched: ${preMatch}`}>👨‍⚕️</span>}
                    </div>
                  }
                  <div style={{display:'flex',alignItems:'center',gap:5,marginLeft:'auto',whiteSpace:'nowrap',flexShrink:0}}>
                    <span style={{fontSize:10,color:'#94A3B8'}}>{time}</span>
                    {isCash&&<span style={{fontSize:8,background:'#FEF3C7',color:'#92400E',borderRadius:3,padding:'0 3px',fontWeight:700}}>CASH</span>}
                    <span style={{fontWeight:800,fontSize:13,color:'#1B3A5C'}}>{fmt$(amt)}</span>
                  </div>
                </div>
                {/* Line 2: notes · line items inline */}
                {(txn.note||docNoteText||lineItems.length>0)&&(
                  <div style={{fontSize:10,color:'#64748B',marginBottom:3,display:'flex',gap:6,flexWrap:'wrap'}}>
                    {txn.note&&<span style={{color:'#475569',fontStyle:'italic'}}>"{txn.note}"</span>}
                    {docNoteText&&<span style={{color:'#92400E'}}>📝 {docNoteText}</span>}
                    {lineItems.length>0&&<span>{lineItems.map(it=>`${it.name} ${fmt$((it.base_price_money?.amount||0)/100*(it.quantity||1))}`).join(' · ')}</span>}
                  </div>
                )}
                {/* Line 3: actions */}
                {!isLinked&&(
                  <div style={{display:'flex',gap:4}}>
                    {(overrideId||entry)&&(
                      <button onClick={()=>doWrite(txn, overrideId?locEntries.find(e=>e.id===overrideId):entry)} disabled={isApproving}
                        style={{background:'#1B3A5C',color:'white',border:'none',borderRadius:4,padding:'2px 10px',cursor:'pointer',fontSize:10,fontWeight:600}}>
                        {isApproving?'...':'Write'}
                      </button>
                    )}
                    <button onClick={()=>{
                      setSplitAmounts({});setSplitTxn(txn);
                    }} style={{background:'#EFF6FF',color:'#1D4ED8',border:'1px solid #BFDBFE',borderRadius:4,padding:'2px 8px',cursor:'pointer',fontSize:10}}>
                      Split
                    </button>
                    <button onClick={()=>sendToReconcile(txn)}
                      style={{background:'#FEF3C7',color:'#92400E',border:'none',borderRadius:4,padding:'2px 8px',cursor:'pointer',fontSize:10}}>
                      → Reconcile
                    </button>
                  </div>
                )}
              </div>
            ) : <div style={{...cellStyle('#FAFAFA'),opacity:0.3,fontSize:10,color:'#94A3B8'}}>—</div>}

            {/* Doctor log — total LEFT (next to Square amt), name RIGHT (next to billing entry) */}
            {log ? (
              <div style={{...cellStyle('#FAFAFF')}}>
                <div style={{display:'flex',alignItems:'center',gap:4,marginBottom:3}}>
                  {(()=>{
                    const lt=['exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherAmt2'].reduce((s,k)=>s+(parseFloat(log[k])||0),0)-(parseFloat(log.discountAmount)||0);
                    return lt>0?<span style={{fontWeight:800,fontSize:13,color:'#6D28D9'}}>{fmt$(lt)}</span>:null;
                  })()}
                  <span style={{fontWeight:600,fontSize:11,color:'#1B3A5C',marginLeft:'auto',textAlign:'right'}}>{log.patientName}</span>
                  {log.entryType==='followup'&&<span style={{fontSize:8,background:'#FEF3C7',color:'#92400E',borderRadius:3,padding:'0 3px',flexShrink:0}}>Unpaid</span>}
                </div>
                <div style={{fontSize:10,color:'#475569'}}>
                  {['exam','cl','optos','oct','dfe','ov'].filter(k=>parseFloat(log[k])>0).map(k=>`${k}:${fmt$(log[k])}`).join(' ')}
                  {parseFloat(log.myopia)>0&&<span style={{color:'#8B5CF6'}}> ⚡{fmt$(log.myopia)}</span>}
                  {parseFloat(log.otherAmt)>0&&<span style={{color:'#475569'}}> {log.otherType||'other'}:{fmt$(log.otherAmt)}</span>}
                  {parseFloat(log.discountAmount)>0&&<span style={{color:'#DC2626'}}> disc:-{fmt$(log.discountAmount)}</span>}
                </div>
                {log.notes&&<div style={{fontSize:10,color:'#94A3B8',fontStyle:'italic',marginTop:2}}>{log.notes}</div>}
              </div>
            ) : <div style={{...cellStyle('#FAFAFA'),opacity:0.3,fontSize:10,color:'#94A3B8'}}>—</div>}

            {/* Billing entry — minimal */}
            {entry ? (
              <div style={{...cellStyle(isLinked?'#F0FDF4':'white'),border:`1px solid ${isLinked?'#6EE7B7':'#E2E8F0'}`}}>
                <div style={{display:'flex',alignItems:'center',gap:4,marginBottom:3}}>
                  <span style={{fontWeight:600,fontSize:11,color:'#1B3A5C'}}>{entry.patientName}</span>
                  {parseFloat(entry.ptPaid)>0&&<span style={{marginLeft:'auto',fontWeight:800,fontSize:13,color:'#16A34A'}}>{fmt$(entry.ptPaid)}</span>}
                </div>
                {(entry.squareTransactionId||entry.squareTransactionIds?.length>0)&&<div style={{fontSize:10,color:'#065F46'}}>💳 matched</div>}
              </div>
            ) : <div style={{...cellStyle('#FAFAFA'),opacity:0.3,fontSize:10,color:'#94A3B8'}}>—</div>}

          </div>
        );
      })}

      {rows.length===0&&!loading&&(
        <div style={{textAlign:'center',padding:20,color:'#94A3B8',fontSize:12}}>No data for {date} {loc}</div>
      )}

      {/* Done Matching button + summary */}
      {txns&&txns.length>0&&!doneMatching&&(
        <div style={{marginTop:8,display:'flex',justifyContent:'flex-end'}}>
          <button onClick={()=>setDoneMatching(true)}
            style={{background:'#F0FDF4',color:'#065F46',border:'1px solid #6EE7B7',borderRadius:7,padding:'5px 14px',cursor:'pointer',fontSize:11,fontWeight:600}}>
            ✓ Done Matching
          </button>
        </div>
      )}
      {doneMatching&&(()=>{
        const unmatchedSq=(txns||[]).filter(txn=>{
          const note=txn.note||'';
          const match=locEntries.map(e=>({e,score:squareNameSim(note,e.patientName)})).filter(m=>m.score>0.3)[0]?.e;
          return !match||(!(match.squareTransactionId===txn.id)&&!(Array.isArray(match.squareTransactionIds)&&match.squareTransactionIds.includes(txn.id)));
        });
        const unmatchedLogs=locDoctorLogs.filter(log=>{
          return !(txns||[]).some(txn=>squareNameSim(txn.note||'',log.patientName)>0.3);
        });
        return (
          <div style={{marginTop:8,background:'#FAFAFA',border:'1px solid #E2E8F0',borderRadius:8,padding:'12px 14px'}}>
            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:10}}>
              <span style={{fontSize:12,fontWeight:700,color:'#1B3A5C'}}>Matching Summary</span>
              <button onClick={()=>setDoneMatching(false)} style={{marginLeft:'auto',background:'none',border:'none',cursor:'pointer',fontSize:11,color:'#94A3B8'}}>← Back</button>
            </div>
            {unmatchedSq.length===0&&unmatchedLogs.length===0&&(
              <div style={{fontSize:12,color:'#065F46',fontWeight:600}}>✓ All transactions matched!</div>
            )}
            {unmatchedSq.length>0&&(
              <div style={{marginBottom:10}}>
                <div style={{fontSize:11,fontWeight:700,color:'#DC2626',marginBottom:6}}>⚠ Unmatched Square transactions — possible missing payments:</div>
                {unmatchedSq.map(txn=>{
                  const amt=(txn.amount_money?.amount||0)/100;
                  return (
                    <div key={txn.id} style={{display:'flex',alignItems:'center',gap:8,padding:'4px 8px',background:'#FEF2F2',borderRadius:5,marginBottom:3,fontSize:11}}>
                      <span style={{fontWeight:700,color:'#1B3A5C'}}>{fmt$((txn.amount_money?.amount||0)/100)}</span>
                      <span style={{color:'#94A3B8'}}>{fmtTime(txn.created_at)}</span>
                      {txn.note&&<span style={{color:'#475569',fontStyle:'italic'}}>"{txn.note}"</span>}
                      <button onClick={()=>sendToReconcile(txn)} style={{marginLeft:'auto',background:'#FEF3C7',color:'#92400E',border:'none',borderRadius:4,padding:'1px 8px',cursor:'pointer',fontSize:10}}>→ Reconcile</button>
                    </div>
                  );
                })}
              </div>
            )}
            {unmatchedLogs.length>0&&(
              <div>
                <div style={{fontSize:11,fontWeight:700,color:'#92400E',marginBottom:6}}>⚠ Doctor log entries without Square payment:</div>
                {unmatchedLogs.map(log=>(
                  <div key={log.id} style={{padding:'4px 8px',background:'#FFFBEB',borderRadius:5,marginBottom:3,fontSize:11,color:'#1B3A5C'}}>
                    {log.patientName} {log.entryType==='followup'&&<span style={{fontSize:8,background:'#FEF3C7',color:'#92400E',borderRadius:3,padding:'0 3px',marginLeft:4}}>Unpaid</span>}
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      })()}
    </div>
  );
}

